+		callable_mp(this, &CSGShape2D::_update_shape).call_deferred();
+		parent_shape->_make_dirty();
+	} else if (!dirty) {
+		callable_mp(this, &CSGShape2D::_update_shape).call_deferred();
+	}
+
+	dirty = true;
+}
