+	Clipper2Lib::PathsD polygon_paths = n->poly_paths;
+
+	for (int i = 0; i < get_child_count(); i++) {
+		CSGShape2D *child = Object::cast_to<CSGShape2D>(get_child(i));
+		if (!child || !child->is_visible()) {
+			continue;
+		}
+		CSGBrush2D *child_brush = child->_get_brush();
+		if (!child_brush) {
